const families = [
  {id:'web-python', title:'Verificar documentación oficial de Python y Flask', technologies:'Python, Flask 3.0.0, Werkzeug 3.0.1, Flask-Login 0.6.3, Flask-WTF 1.2.1, python-dotenv 1.0.0. Fuentes: documentación oficial Python/Palettes/Flask-Login/Flask-WTF/python-dotenv.'},
  {id:'database', title:'Verificar PostgreSQL, JSONB, Supabase y Psycopg', technologies:'PostgreSQL, JSONB, psycopg 3.2.3, Supabase. Fuentes: PostgreSQL docs, Psycopg 3 docs, Supabase official docs.'},
  {id:'ai-sdk', title:'Verificar OpenAI SDK, OpenRouter, Gemini y Pydantic', technologies:'OpenAI Python SDK, OpenRouter API, Google GenAI SDK, Gemini, Pydantic. Fuentes oficiales de cada proveedor y biblioteca.'},
  {id:'browser-ui', title:'Verificar estándares web y gráficos Chart.js', technologies:'HTML, CSS, JavaScript, Chart.js 4.5.1, Web Speech API. Fuentes: WHATWG/W3C/MDN como documentación técnica oficial, Chart.js docs.'},
  {id:'maps-geo', title:'Verificar mapas y geolocalización del proyecto', technologies:'Leaflet, MapLibre GL JS, OpenStreetMap tile usage policy, geopy 2.4.1, haversine 2.8.0. Preferir documentación oficial.'},
  {id:'data-media', title:'Verificar librerías de datos, importación y medios', technologies:'Pillow, pandas, openpyxl, python-docx, qrcode, cryptography. Fuentes oficiales de proyectos y documentación.'},
  {id:'immersive', title:'Verificar visor 3D, GLB y voz del navegador', technologies:'model-viewer 4.1.0, GLB/glTF, Web Speech API y trimesh 4.6.13 (solo construcción de activos). Fuentes Google/model-viewer, Khronos, MDN/W3C y docs del paquete.'},
  {id:'testing', title:'Verificar pytest, Playwright y Node.js', technologies:'pytest, Playwright, Node.js. Documentación oficial para pruebas, navegadores y runtime.'}
];
const schema = JSON.stringify({type:'object',properties:{family:{type:'string'},technologies:{type:'array',items:{type:'object',properties:{name:{type:'string'},repository_version_or_range:{type:'string'},external_claims:{type:'array',items:{type:'string'}},citations:{type:'array',items:{type:'object',properties:{author_or_org:{type:'string'},title:{type:'string'},date_or_year:{type:'string'},url:{type:'string'},apa7_reference:{type:'string'},supports:{type:'array',items:{type:'string'}}},required:['author_or_org','title','date_or_year','url','apa7_reference','supports']}},caveat:{type:'string'}},required:['name','repository_version_or_range','external_claims','citations','caveat']}},limitations:{type:'array',items:{type:'string'}}},required:['family','technologies','limitations']});
const results = await parallel('Fuentes primarias para justificación tecnológica', () => families.map(f => agent(
  'Investiga fuentes externas solo para la familia tecnológica asignada; no inspecciones ni modifiques el proyecto SmartResto. Familia: ' + f.id + '. Elementos: ' + f.technologies + '. Usa funciones de búsqueda web y después abre/extrae las URLs oficiales encontradas; no dependas de snippets. Prefiere documentación oficial del proyecto/estándar. Devuelve solo afirmaciones que la fuente respalde y referencias APA 7 con organización/autores, título, fecha tal como aparece, URL y fecha de recuperación 19 de noviembre de 2026 si la página no tiene fecha. Si no puedes verificar un dato, dilo. No afirmes versiones instaladas: el rango/pinning proviene de requirements.txt indicado en la familia, y se debe marcar como requisito del repositorio, no inventar versión de runtime. No hagas solicitudes a servicios funcionales, no uses ejemplos promocionales como evidencia de SmartResto. Respeta el esquema común.',
  {brief:f.title, schema, sandbox:'isolated', effort_level:'standard'}
)), {schema});
const successful = results.filter(r=>r.ok).map(r=>r.value);
const failures = results.map((r,i)=>r.ok?null:{family:families[i].id,code:r.error.code,message:r.error.message}).filter(Boolean);
const reducerSchema = JSON.stringify({type:'object',properties:{citations:{type:'array',items:{type:'object',properties:{id:{type:'string'},author_or_org:{type:'string'},year_or_date:{type:'string'},title:{type:'string'},url:{type:'string'},apa7_reference:{type:'string'},supported_claims:{type:'array',items:{type:'string'}}},required:['id','author_or_org','year_or_date','title','url','apa7_reference','supported_claims']}},technology_justifications:{type:'array',items:{type:'object',properties:{technology:{type:'string'},technical_role:{type:'string'},justification:{type:'string'},limitations:{type:'string'},citation_ids:{type:'array',items:{type:'string'}}},required:['technology','technical_role','justification','limitations','citation_ids']}},caveats:{type:'array',items:{type:'string'}},source_gaps:{type:'array',items:{type:'string'}}},required:['citations','technology_justifications','caveats','source_gaps']});
const reduced=await agent('Sintetiza estas fuentes oficiales en un catálogo de justificaciones de tecnologías usadas por SmartResto. Conserva límites y versiones/rangos declarados en requirements; no afirmes que una biblioteca ya se ejecutó. Reutiliza las referencias APA entregadas y no añadas URLs no verificadas. Devuelve catálogo breve de roles/ventajas/limitaciones con citas IDs y lista alfabética o usable para referencias. Material: '+JSON.stringify(successful)+' Fallos: '+JSON.stringify(failures),{brief:'Sintetizar justificaciones y referencias APA',schema:reducerSchema,sandbox:'isolated',effort_level:'standard'});
return {families:successful,failures,synthesis:reduced.ok?reduced.value:null,reducer_error:reduced.ok?null:{code:reduced.error.code,message:reduced.error.message}};

